begin;
create function pg_temp.expect_error(q text, expected text) returns void language plpgsql as $$ begin
 begin execute q; exception when others then if strpos(sqlerrm,expected)>0 then return; else raise; end if; end;
 raise exception 'Expected failure: %',expected;
end $$;
create function pg_temp.check_true(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'Failed: %',label; end if; end $$;
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
 select ('00000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'user'||n||'@example.com',case when n=7 then null else now() end,'{"full_name":"Researcher"}' from generate_series(1,7)n;
insert into public.online_projects(id,owner_id,title,request_id) values('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000001','Shared project',gen_random_uuid());
