select pg_temp.expect_error($q$insert into public.online_project_members values('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000006','editor',now())$q$,'permission denied');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000006","email":"user2@example.com"}';
select pg_temp.check_true((select count(*) from public.online_projects)=0,'Non-member project hidden');
