set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000002"}';
select public.respond_online_project_invitation((public.list_online_project_invitations()->0->>'id')::uuid,true);
select pg_temp.check_true(public.get_online_project_access('20000000-0000-4000-8000-000000000010')->>'role'='editor','Editor access granted');
select pg_temp.check_true((public.get_online_project_sharing('20000000-0000-4000-8000-000000000010')->>'usedSeats')::int=5,'Accept consumes reserved seat');
select pg_temp.expect_error($q$select public.invite_online_project_member('20000000-0000-4000-8000-000000000010','user6@example.com','viewer')$q$,'COLLAB_OWNER_REQUIRED');
select pg_temp.expect_error($q$select public.commit_online_project_data('20000000-0000-4000-8000-000000000010',1,gen_random_uuid(),10,'[{"table":"src_text_versions","after":{"state":"confirmed"},"before":null}]')$q$,'COLLAB_CONFIRM_OWNER_REQUIRED');
select pg_temp.check_true(private.online_asset_access('00000000-0000-4000-8000-000000000001/20000000-0000-4000-8000-000000000010/'||repeat('a',64),true),'Editor can upload under owner prefix');
select pg_temp.check_true(not private.online_asset_access('00000000-0000-4000-8000-000000000002/20000000-0000-4000-8000-000000000010/'||repeat('a',64),true),'Wrong asset prefix denied');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000003"}';
select public.respond_online_project_invitation((public.list_online_project_invitations()->0->>'id')::uuid,true);
select pg_temp.check_true(public.get_online_project_access('20000000-0000-4000-8000-000000000010')->>'role'='viewer','Viewer access granted');
