select pg_temp.check_true(not private.online_asset_access('00000000-0000-4000-8000-000000000001/20000000-0000-4000-8000-000000000010/'||repeat('a',64),true),'Viewer storage write denied');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000001"}';
select public.update_online_project_member('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000002','viewer');
select public.update_online_project_member('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000003',null);
select pg_temp.expect_error($q$select public.update_online_project_member('20000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000001',null)$q$,'COLLAB_OWNER_IMMUTABLE');
select public.invite_online_project_member('20000000-0000-4000-8000-000000000010','user7@example.com','viewer');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000007"}';
select pg_temp.check_true(public.list_online_project_invitations()='[]'::jsonb,'Unverified email cannot accept invitations');
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000002"}';
select pg_temp.expect_error($q$select public.commit_online_project_data('20000000-0000-4000-8000-000000000010',1,gen_random_uuid(),10,'[]')$q$,'COLLAB_WRITE_REQUIRED');
