set local role authenticated;
set local request.jwt.claims='{"sub":"00000000-0000-4000-8000-000000000001"}';
select pg_temp.check_true(not (public.get_online_project_sharing('20000000-0000-4000-8000-000000000010')->>'canInvite')::boolean,'Unrelated Stripe price does not grant Premium');
